{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Pridopidine, a close analogue with an N-propyl piperidine and similar tertiary-amine/aromatic character, showed high oral availability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alpidem, which contains an N,N-dipropyl amide and heteroaromatic core, had an absolute oral bioavailability of 32% in humans, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PNU-96391, structurally similar to pridopidine, had an absolute oral bioavailability of 0.6 (60%) in healthy volunteers, supporting high oral availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Proterguride, a basic amine ergoline analogue, showed 62% oral bioavailability in humans, supporting high F for a lipophilic basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "BMS-275183 had 24% oral bioavailability in humans, providing a threshold-relevant example that moderate first-pass liability can still yield F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tasimelteon, a fused-ring lactam-like drug, had approximately 38% absolute oral bioavailability in humans, supporting high F for the query's fused bicyclic lactam motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Meptazinol showed low absolute oral bioavailability around 8.7% in humans, but its phenol group drives extensive glucuronidation, a liability absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most high-transfer human analogues, including close N,N-dipropylamine and fused-ring structures, show absolute oral bioavailability ≥20% (24–100%). The only low-F analogue, meptazinol, has a phenolic glucuronidation liability not present in the query. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Human first-pass metabolism and transporter interactions for the query are unknown.",
    "The exact contribution of the lactam group to metabolic stability is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

